public final class CliOptions {private final CliCommand command;private final Path workspace,answerFile,config;private final String tenant,user,runId,goal,skill,interactionId;private final WorkspaceAccessMode mode;private final CliUiMode ui;private final CliOutputFormat output;private final boolean approve,noColor;
 CliOptions(CliCommand command,Path workspace,Path answerFile,Path config,String tenant,String user,String run,String goal,String skill,String interaction,WorkspaceAccessMode mode,CliUiMode ui,CliOutputFormat output,boolean approve,boolean noColor){this.command=command;this.workspace=workspace;this.answerFile=answerFile;this.config=config;this.tenant=tenant;this.user=user;runId=run;this.goal=goal;this.skill=skill;interactionId=interaction;this.mode=mode;this.ui=ui;this.output=output;this.approve=approve;this.noColor=noColor;}public CliCommand getCommand(){return command;}public Path getWorkspace(){return workspace;}public Path getAnswerFile(){return answerFile;}public Path getConfig(){return config;}public String getTenant(){return tenant;}public String getUser(){return user;}public String getRunId(){return runId;}public String getGoal(){return goal;}public String getSkill(){return skill;}public String getInteractionId(){return interactionId;}public WorkspaceAccessMode getMode(){return mode;}public CliUiMode getUi(){return ui;}public CliOutputFormat getOutput(){return output;}public boolean isApprove(){return approve;}public boolean isNoColor(){return noColor;}}
